// Fluxo de ENTRADA: Z-API -> CRM
// Corrige áudio da Z-API: body.type costuma vir como "ReceivedCallback", então o tipo real vem pela existência de body.audio.audioUrl.
const body = $json.body || {};

const textMessage =
  body.text?.message ||
  (typeof body.text === 'string' ? body.text : null) ||
  body.message ||
  body.caption ||
  body.content ||
  null;

const audioUrl =
  body.audio?.audioUrl ||
  body.audio?.url ||
  body.audio?.link ||
  body.audioUrl ||
  body.mediaUrl ||
  body.url_midia ||
  null;

const rawMessageType = String(body.messageType || body.typeMessage || body.kind || body.tipo || '').toLowerCase();
const isAudio = Boolean(audioUrl) || ['audio', 'voice', 'ptt'].includes(rawMessageType);

const chatId = body.chatId || body.phone || body.remoteJid || body.from || null;
const phone = body.phone || body.sender || body.participantPhone || chatId;
const isGroup =
  body.isGroup === true ||
  body.isGroup === 'true' ||
  String(chatId || '').includes('-group') ||
  String(chatId || '').includes('@g.us') ||
  String(body.phone || '').includes('-group') ||
  String(body.phone || '').includes('@g.us');

const groupName = body.chatName || body.groupName || body.group?.name || null;
const contactName = body.senderName || body.name || body.profileName || body.pushName || null;

// Em grupo: p_photo = foto do grupo. p_sender_photo = foto individual de quem falou.
// Não use body.photo como foto do participante em grupo se ela vier como foto do grupo.
const groupPhoto = body.chatPhoto || body.groupPhoto || body.groupPicture || body.group?.photo || (isGroup ? body.photo : null) || null;
const contactPhoto = body.senderPhoto || body.participantPhoto || body.participantPicture || body.sender?.photo || body.contact?.photo || null;
const oneToOnePhoto = body.photo || body.profilePicUrl || body.senderPhoto || null;

return [{
  json: {
    p_secret: body.secret || body.webhook_secret || 'kpwh_72793a36df318e7593cc8bf97478d99b',
    p_instance_id: body.instance_id || body.instanceId || body.instanceIdZapi || body.instance,
    p_phone: phone,
    p_nome: isGroup ? (groupName || chatId || phone) : (contactName || body.chatName || phone),
    p_texto: textMessage,
    p_message_id: body.messageId || body.id || body.message_id,
    p_is_group: isGroup,
    p_chat_id: chatId,
    p_photo: isGroup ? groupPhoto : oneToOnePhoto,
    p_sender_photo: isGroup ? contactPhoto : null,
    p_participant_phone: isGroup ? (body.participantPhone || body.author || body.sender || body.phone) : null,
    p_participant_name: isGroup ? (body.participantName || body.participant || body.senderName || body.name) : null,
    p_tipo: isAudio ? 'audio' : 'texto',
    p_url_midia: isAudio ? audioUrl : null
  }
}];
